import React, { useEffect, useState } from "react";
import * as Yup from "yup";
import {
  ModalContent,
  ModalHeader,
  ModalBody,
  ModalFooter,
  Button,
  useDisclosure,
  Checkbox,
  Input,
  Link,
  Textarea,
} from "@heroui/react";
import {
  CustomForm,
  CustomFormItem,
  CustomInput,
  Loading,
  CustomTimePicker,
} from "../../../components";
import { useFormik } from "formik";
import useApi from "../../../hooks/useApi";

import { ToastContainer, toast } from "react-toastify";
import transportApi from "../../../api/transport/transportApi";
import CustomTextArea from "../../../components/forms/CustomTextArea";
import { Modal } from "antd";
import dayjs from "dayjs";

export default function RoutesFormModal({
  ismodalOpen,
  setisModalOpen,
  route,
  modalTitle = "Add new route",
  updated,
  setUpdated,
}) {
  // const { isOpen, onOpen, onOpenChange } = useDisclosure();

  console.log("Opening", ismodalOpen);

  const [errors, setErrors] = useState();
  const transportActionsApi = useApi(transportApi.transportAction);

  const handleRouteAction = async (data) => {
    const result = await transportActionsApi.request(data);

    if (result.ok) {
      setUpdated(true);
      setisModalOpen(false);
    } else {
      setUpdated(false);
    }
  };

  const handlePeakStartTimeChange = (timeArray, time) => {
    formik.setFieldValue("peak_start", time);
  };

  const handlePeakEndTimeChange = (timeArray, time) => {
    formik.setFieldValue("peak_end", time);
  };

  useEffect(() => {}, [route]);

  useEffect(() => {
    if (errors && errors.length) {
      errors.map((x) => {
        toast.error(x);
      });
    }
  }, [errors]);

  const formik = useFormik({
    initialValues: {
      title: route ? route.title : "",
      description: route ? route.description : "",
      peak_start: route ? route.peak_start : "00:00",
      peak_end: route ? route.peak_end : "00:00",
    },

    validationSchema: Yup.object({
      title: Yup.string()
        .min(3, "Must be 15 characters or more")
        .required("Title is required"),
    }),
    onSubmit: (values, { resetForm }) => {
      //Dispatch action

      console.log("VALZ", values);
      setErrors([]);

      if (route) {
        handleRouteAction({
          action: "UpdateOperationalRoute",
          route_details: {
            route_id: route.id,
            title: values.title,
            peak_start: values.peak_start,
            peak_end: values.peak_end,
            description: values.description ? values.description : "",
          },
        });
      } else {
        handleRouteAction({
          action: "CreateOperationalRoute",
          route_details: {
            title: values.title,
            peak_start: values.peak_start,
            peak_end: values.peak_end,
            description: values.description ? values.description : "",
          },
        });
      }

      resetForm();
    },
  });

  const handleOk = () => {
    setisModalOpen(false);
  };
  const handleCancel = () => {
    setisModalOpen(false);
  };

  return (
    <div className="w-full">
      <Modal
        width={560}
        className="w-full text-center"
        title={modalTitle}
        open={ismodalOpen}
        onOk={handleOk}
        onCancel={handleCancel}
        cancelButtonProps={{ style: { display: "none" } }}
        okButtonProps={{ style: { display: "none" } }}
      >
        <ToastContainer theme="colored" position="bottom-center" />

        <CustomForm
          layout="vertical"
          handleFinish={formik.handleSubmit}
          className=" flex flex-col justify-center items-center w-full my-7"
        >
          <CustomFormItem
            touched={formik.touched.title}
            error={formik.errors.title}
          >
            <CustomInput
              required={true}
              id="title"
              name="title"
              onChange={formik.handleChange}
              placeholder="Enter route title"
              size="large"
              type="text"
              value={formik.values.title}
              label="Route title"
            />
          </CustomFormItem>

          <CustomFormItem
            touched={formik.touched.departure_time}
            error={formik.errors.departure_time}
          >
            <CustomTimePicker
              id="peak_start"
              name="peak_start"
              size="large"
              defaultValue={dayjs(formik.values.peak_start, "HH:mm")}
              placeholder="Peak start time"
              onChange={handlePeakStartTimeChange}
            />
          </CustomFormItem>
          <CustomFormItem
            touched={formik.touched.departure_time}
            error={formik.errors.departure_time}
          >
            <CustomTimePicker
              id="peak_end"
              name="peak_end"
              size="large"
              defaultValue={dayjs(formik.values.peak_end, "HH:mm")}
              placeholder="Peak end time"
              onChange={handlePeakEndTimeChange}
            />
          </CustomFormItem>
          <CustomFormItem
            touched={formik.touched.description}
            error={formik.errors.description}
          >
            <CustomTextArea
              required={true}
              id="description"
              name="description"
              onChange={formik.handleChange}
              placeholder="Enter short description of the subscription"
              size="large"
              type="text"
              rows={2}
              value={formik.values.description}
            />
          </CustomFormItem>

          <div className="w-full items-center mt-2">
            <Button className="w-36 rounded-md" color="primary" type="submit">
              Submit
            </Button>
          </div>
        </CustomForm>
      </Modal>
    </div>
  );
}
